def receipt_created(ws):
    path = Path(ws) / "应收账款会计估计调整回执.md"
    if not path.is_file():
        return {"score": 0, "detail": "缺少应收账款会计估计调整回执.md"}
    text = path.read_text(encoding="utf-8", errors="replace")
    normalized = re.sub(r"[,，\s]", "", text)
    required = [
        "银江技术股份有限公司",
        "670102",
        "信用减值损失",
        "123102",
        "应收账款坏账准备",
        "137492903.92",
        "RUN-AUD-YJ-2024-1231-03",
        "2,592,609.53",
    ]
    missing = [x for x in required if re.sub(r"[,，\s]", "", x) not in normalized]
    dates = re.findall(r"\b\d{4}-\d{2}-\d{2}\b", text)
    date_ok = any(value >= "2024-10-01" for value in dates)
    excluded = any(term in text for term in ("不包含", "不计入", "未包含", "排除")) and ("合同资产" in text)
    if missing or not date_ok or not excluded:
        detail = "回执缺少: " + ", ".join(missing)
        if not date_ok:
            detail += "; 未找到不早于2024-10-01的登记日期"
        if not excluded:
            detail += "; 未明确合同资产金额不包含在本笔登记中"
        return {"score": 0, "detail": detail}
    return {"score": 1, "detail": "回执包含主体、日期、科目、金额、来源及合同资产排除说明"}


