def _rows_hash(rows):
    payload = "\n".join(repr(tuple(row)) for row in rows)
    return sha256(payload.encode("utf-8")).hexdigest()


def _parse_time(value):
    try:
        return datetime.fromisoformat(str(value))
    except (TypeError, ValueError):
        return None


def _norm(value):
    return re.sub(r"[\s，,。；;：:、（）()\-_/]+", "", str(value or "")).lower()


def _target_events(connection, event_type):
    connection.row_factory = sqlite3.Row
    return connection.execute(
        "SELECT * FROM task_events WHERE task_id = ? AND event_type = ? ORDER BY event_at, event_id",
        (TARGET_TASK_ID, event_type),
    ).fetchall()


def check_new_archive_evidence_submitted(ws):
    path = _db_path(ws)
    if not path.exists():
        return {"score": 0, "detail": "整改跟踪系统数据库不存在"}
    with sqlite3.connect(path) as connection:
        rows = _target_events(connection, "evidence_submitted")
    if len(rows) != 1:
        return {"score": 0, "detail": f"目标任务应有且仅有一个新 evidence_submitted 事件，实际 {len(rows)} 个"}
    row = rows[0]
    submitted_at = _parse_time(row["event_at"])
    evidence_id = str(row["evidence_id"] or "").strip()
    if submitted_at is None or submitted_at <= BASELINE_LATEST_EVENT:
        return {"score": 0, "detail": f"证据提交时间未晚于既有最新事件: {row['event_at']}"}
    if row["actor_id"] != OWNER_ID:
        return {"score": 0, "detail": f"证据提交人不是任务责任人袁菲: {row['actor_id']}"}
    if not evidence_id.startswith(ORIGINAL_EVIDENCE_ID) or evidence_id == ORIGINAL_EVIDENCE_ID:
        return {"score": 0, "detail": f"新证据包未沿用主编号并区分第二轮补证: {evidence_id!r}"}
    suffix = _norm(evidence_id[len(ORIGINAL_EVIDENCE_ID):])
    if not any(marker in suffix for marker in ("r2", "round2", "v2", "第二轮", "二次", "补证")):
        return {"score": 0, "detail": f"新证据包编号没有明确的第二轮/补证标识: {evidence_id!r}"}
    if row["from_status"] != "in_progress" or row["to_status"] != "evidence_submitted":
        return {"score": 0, "detail": "证据提交事件没有从原整改中状态进入证据已提交状态"}

    text = _norm(row["review_comment"])
    semantic_checks = {
        "纸质卷移交/接收": "纸质" in text and any(token in text for token in ("移交", "接收", "入档")),
        "电子目录挂接/关联": "电子" in text and "目录" in text and any(token in text for token in ("挂接", "关联", "链接")),
        "数量一致": any(token in text for token in ("数量一致", "数量相符", "数目一致", "核对一致")),
        "质量检查通过": "质量" in text and any(token in text for token in ("通过", "合格", "验收")),
    }
    missing = [name for name, ok in semantic_checks.items() if not ok]
    if missing:
        return {"score": 0, "detail": "证据说明缺少闭环事实: " + "、".join(missing)}
    return {"score": 1, "detail": f"新补证包 {evidence_id} 由责任人于 {row['event_at']} 合法提交，四类归档证据齐全"}


