    reviewed_at = _parse_time(passed[0]["event_at"])
    if passed[0]["actor_id"] != REVIEWER_ID:
        return {"score": 0, "detail": f"通过复核人不是陈璟怡: {passed[0]['actor_id']}"}
    if submitted_at is None or reviewed_at is None or reviewed_at <= submitted_at:
        return {"score": 0, "detail": "复核时间没有严格晚于证据提交时间"}
    if passed[0]["evidence_id"] != evidence[0]["evidence_id"]:
        return {"score": 0, "detail": "复核事件没有引用最新补证包"}
    if passed[0]["from_status"] != "evidence_submitted" or passed[0]["to_status"] != "completed":
