        return {"score": 0, "detail": "closed 事件没有晚于 review_passed 事件"}
    if closed[0]["evidence_id"] != evidence[0]["evidence_id"]:
        return {"score": 0, "detail": "销号事件没有引用本次补证包"}
    if closed[0]["actor_id"] != REVIEWER_ID:
        return {"score": 0, "detail": "销号事件不是由复核人形成"}
    if closed[0]["from_status"] != "completed" or closed[0]["to_status"] != "closed":
        return {"score": 0, "detail": "closed 事件的状态迁移不符合闭环状态机"}
    stored_date = str(task["closed_at"] or "").strip()
    if task["task_status"] != "closed" or not stored_date:
        return {"score": 0, "detail": f"目标任务未正式 closed: {dict(task)}"}
    try:
        stored_day = datetime.fromisoformat(stored_date).date()
    except ValueError:
        return {"score": 0, "detail": f"任务销号日期无法解析: {stored_date!r}"}
    if stored_day != closed_at.date():
        return {"score": 0, "detail": "任务销号日期与 closed 事件日期不一致"}
    return {"score": 1, "detail": f"目标任务已于 {stored_date} 正式销号，完整事件链顺序正确"}


def check_database_scope_integrity(ws):
    path = _db_path(ws)
    if not path.exists():
        return {"score": 0, "detail": "整改跟踪系统数据库不存在"}
    with sqlite3.connect(path) as connection:
        non_target_tasks = connection.execute(
            "SELECT * FROM rectification_tasks WHERE task_id <> ? ORDER BY task_id",
            (TARGET_TASK_ID,),
        ).fetchall()
        non_target_events = connection.execute(
            "SELECT * FROM task_events WHERE task_id <> ? ORDER BY event_id",
            (TARGET_TASK_ID,),
        ).fetchall()
        departments = connection.execute(
            "SELECT * FROM responsible_departments ORDER BY rowid"
        ).fetchall()
        target_history = connection.execute(
            "SELECT * FROM task_events WHERE task_id = ? AND event_type = 'note' ORDER BY event_id",
            (TARGET_TASK_ID,),
        ).fetchall()
        target_fixed = connection.execute(
            """
            SELECT task_id, finding_id, matter_id, agency_id, region_id, department_id,
                   issue_type, task_title, owner_id, measure, due_at,
                   review_baseline_date_id, review_baseline_date, review_chair_id
            FROM rectification_tasks WHERE task_id = ?
            """,
            (TARGET_TASK_ID,),
        ).fetchone()
        target_new_events = connection.execute(
            "SELECT event_type, COUNT(*) FROM task_events WHERE task_id = ? AND event_type <> 'note' GROUP BY event_type ORDER BY event_type",
            (TARGET_TASK_ID,),
        ).fetchall()
    checks = {
        "非目标任务": (_rows_hash(non_target_tasks), NON_TARGET_TASKS_HASH),
        "非目标事件": (_rows_hash(non_target_events), NON_TARGET_EVENTS_HASH),
        "责任部门表": (_rows_hash(departments), DEPARTMENTS_HASH),
        "目标既有历史记录": (_rows_hash(target_history), TARGET_HISTORY_HASH),
    }
    changed = [name for name, (actual, expected) in checks.items() if actual != expected]
    expected_fixed = (
        "RT-2025-071-019", "FIND-QP-SEAL-2025-019", "SEALMAT-2025-0130",
        "ORG_QP_WATER_001", "REGION_SH_QINGPU", "DEPT_QP_WATER_ARCHIVES",
        "台账未归档", "2025年5月用印登记台账未归档", "PERSON_YUAN_FEI",
        "按月归档登记表和备案材料，提交目录", "2025-07-16",
        "DATE_2025_07_18", "2025-07-18", "PERSON_CHEN_JINGYI",
    )
    if target_fixed is None or tuple(target_fixed) != expected_fixed:
        changed.append("目标任务非状态属性")
    allowed_counts = {"evidence_submitted": 1, "review_passed": 1, "closed": 1}
    if any(event_type not in allowed_counts or count > allowed_counts[event_type]
           for event_type, count in target_new_events):
        changed.append("目标任务出现越界新增事件")
    if changed:
        return {"score": 0, "detail": "发生越界改动: " + "、".join(changed)}
    return {"score": 1, "detail": "仅目标任务当前状态和新增闭环事件发生变化，其他数据库内容保持不变"}


def check_workspace_source_integrity(ws):
    root = Path(ws)
    bad = []
    for relative, expected in WORKSPACE_HASHES.items():
        path = root / relative
        if not path.exists():
            bad.append(f"缺失:{relative}")
        elif sha256(path.read_bytes()).hexdigest() != expected:
            bad.append(f"改写:{relative}")
    if bad:
        return {"score": 0, "detail": "；".join(bad[:5])}
    return {"score": 1, "detail": "全部既有 workspace 原始材料保持不变"}

